{
   "title": "PairsWatchlist",
   "description": "Dataclass that represents a pairs watchlist object.",
   "type": "object",
   "properties": {
      "name": {
         "title": "Name",
         "type": "string"
      },
      "order-index": {
         "title": "Order-Index",
         "type": "integer"
      },
      "pairs-equations": {
         "items": {
            "$ref": "#/$defs/Pair"
         },
         "title": "Pairs-Equations",
         "type": "array"
      }
   },
   "$defs": {
      "Pair": {
         "description": "Dataclass that represents a specific pair in a pairs watchlist.",
         "properties": {
            "left-action": {
               "title": "Left-Action",
               "type": "string"
            },
            "left-symbol": {
               "title": "Left-Symbol",
               "type": "string"
            },
            "left-quantity": {
               "title": "Left-Quantity",
               "type": "integer"
            },
            "right-action": {
               "title": "Right-Action",
               "type": "string"
            },
            "right-symbol": {
               "title": "Right-Symbol",
               "type": "string"
            },
            "right-quantity": {
               "title": "Right-Quantity",
               "type": "integer"
            }
         },
         "required": [
            "left-action",
            "left-symbol",
            "left-quantity",
            "right-action",
            "right-symbol",
            "right-quantity"
         ],
         "title": "Pair",
         "type": "object"
      }
   },
   "required": [
      "name",
      "order-index",
      "pairs-equations"
   ]
}

{
   "title": "PrivateWatchlist",
   "description": "Dataclass that contains a private watchlist object, with functions to\nupdate, publish, modify and remove watchlists.",
   "type": "object",
   "properties": {
      "name": {
         "title": "Name",
         "type": "string"
      },
      "watchlist-entries": {
         "anyOf": [
            {
               "items": {
                  "additionalProperties": true,
                  "type": "object"
               },
               "type": "array"
            },
            {
               "type": "null"
            }
         ],
         "default": null,
         "title": "Watchlist-Entries"
      },
      "group-name": {
         "default": "default",
         "title": "Group-Name",
         "type": "string"
      },
      "order-index": {
         "default": 9999,
         "title": "Order-Index",
         "type": "integer"
      }
   },
   "required": [
      "name"
   ]
}

